'use strict';
let sharedPaceState=null;
const sharedPaceCurrent=s=>sharedPaceState===s&&$('#dialog').open&&!!$('#shared-pace')&&s.path===dataPath&&s.identity.databaseId===db.id;
async function openSharedPace(id){
 const s={identity:historyIdentity(),path:dataPath,snapshot:null,serial:0,busy:false,error:'',result:null,left:{carId:id||'',query:'',trackQuery:'',carOffset:0,sessionOffset:0,cars:null,sessions:null,choice:null,lane:'',driver:''},right:{carId:'',query:'',trackQuery:'',carOffset:0,sessionOffset:0,cars:null,sessions:null,choice:null,lane:'',driver:''}};sharedPaceState=s;
 modal('Compare pace','<div id="shared-pace" class="shared-history"></div>',null);$('#dialog .dialog-footer [data-action="close-modal"]').textContent='Close';
 await sharedPaceLoad(async()=>{await sharedPaceCars(s,'left');await sharedPaceCars(s,'right');if(s.left.carId)await sharedPaceSessions(s,'left');});
}
async function sharedPaceRead(s,operation,input={}){return api('historyView',{...s.identity,operation,...(s.snapshot?{snapshot:s.snapshot}:{}),...input});}
async function sharedPaceCars(s,side){const p=s[side],result=await sharedPaceRead(s,'pace-cars',{query:p.query,offset:p.carOffset});if(!sharedPaceCurrent(s)||s.stale)return;s.snapshot=result.snapshot;p.cars=result;}
async function sharedPaceSessions(s,side){const p=s[side],result=await sharedPaceRead(s,'pace-sessions',{carId:p.carId,offset:p.sessionOffset,query:p.trackQuery});if(!sharedPaceCurrent(s)||s.stale)return;s.snapshot=result.snapshot;p.sessions=result;}
async function sharedPaceLoad(work){
 const s=sharedPaceState;if(!sharedPaceCurrent(s)||s.busy||s.stale)return;const serial=++s.serial;s.busy=true;s.error='';s.result=null;paintSharedPace();
 try{await work();}catch(e){if(sharedPaceCurrent(s)&&serial===s.serial)s.error=e.message;}
 finally{if(sharedPaceCurrent(s)&&serial===s.serial){s.busy=false;paintSharedPace();}}
}
function sharedPaceSide(p,side){
 const car=p.sessions?.car,selected=p.choice;
 const choices=p.cars?.rows||[],options=car&&!choices.some(c=>c.id===car.id)?[car,...choices]:choices;
 return `<section class="panel shared-pace-side"><h3>${side==='left'?'A · Reference':'B · Compare with'}</h3><div class="shared-pace-search"><label>Find a car<input id="shared-pace-search-${side}" maxlength="200" value="${esc(p.query)}" placeholder="Search recorded cars…"></label>${btn('Search','shared-pace-search','small',side)}</div><label>Car<select data-shared-pace="car" data-side="${side}"><option value="">Choose a car…</option>${options.map(c=>`<option value="${esc(c.id)}" ${c.id===p.carId?'selected':''}>${esc(c.name)}${c.archived?' (archived)':''}</option>`).join('')}</select></label><div class="actions tiny">${p.carOffset?btn('Previous cars','shared-pace-cars-prev','small',side):''}<span>${p.cars?.total??0} cars with accepted history</span>${p.cars?.nextOffset!=null?btn('More cars','shared-pace-cars-next','small',side):''}</div>${p.carId?`<div class="shared-pace-search"><label>Filter by track name<input id="shared-pace-track-${side}" maxlength="200" value="${esc(p.trackQuery)}" placeholder="All tracks"></label>${btn('Filter tracks','shared-pace-track','small',side)}</div><label>Recorded session<select data-shared-pace="session" data-side="${side}"><option value="">Choose a session…</option>${(selected&&!p.sessions?.rows.some(x=>sharedPaceKey(x)===sharedPaceKey(selected))?[selected,...(p.sessions?.rows||[])]:p.sessions?.rows||[]).map(x=>`<option value="${esc(sharedPaceKey(x))}" ${selected&&sharedPaceKey(x)===sharedPaceKey(selected)?'selected':''}>${esc(x.name)} · ${esc(x.track.name||'Unknown track')} · ${esc(historySessionDate(x.startedAt,x.savedAt))} · ${esc(x.sourceId)}</option>`).join('')}</select></label><div class="actions tiny">${p.sessionOffset?btn('Previous sessions','shared-pace-sessions-prev','small',side):''}<span>${p.sessions?.total??0} sessions</span>${p.sessions?.nextOffset!=null?btn('More sessions','shared-pace-sessions-next','small',side):''}</div>`:''}${selected?`<div class="form-grid"><label>Lane<select data-shared-pace="lane" data-side="${side}"><option value="">All lanes</option>${selected.track.lanes.map(l=>`<option value="${l.lane}" ${p.lane===String(l.lane)?'selected':''}>Lane ${l.lane}</option>`).join('')}</select></label><label>Driver<select data-shared-pace="driver" data-side="${side}"><option value="">All drivers</option>${selected.drivers.map(d=>`<option value="${esc(d.id)}" ${p.driver===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label></div>`:''}</section>`;
}
const sharedPaceKey=x=>JSON.stringify([x.sourceId,x.sessionId,x.participantId]);
function sharedPaceSelection(p){const x=p.choice;return {carId:p.carId,sourceId:x.sourceId,sessionId:x.sessionId,participantId:x.participantId,...(p.lane?{lane:Number(p.lane)}:{}),...(p.driver?{driverId:p.driver}:{})};}
function sharedPaceResults(result){
 const a=result.left,b=result.right,rows=[['Average valid lap','averageMs'],['Median valid lap','medianMs'],['Consistency · standard deviation','standardDeviationMs'],['Best personal-eligible lap','bestPersonalMs'],['Best track-eligible lap','bestTrackMs'],['Best uninterrupted 5-lap average','sustained5Ms'],['Best uninterrupted 10-lap average','sustained10Ms']];
 const deltas=rows.map(([label,key])=>{const av=a.metrics[key],bv=b.metrics[key],delta=av===null||bv===null?null:bv-av;return [label,HistoryViewModel.seconds(av),HistoryViewModel.seconds(bv),delta===null?'Unknown':(delta>0?'+':'')+(delta/1000).toFixed(3)+' s'];});
 const details=x=>`<section class="panel"><h3>${esc(x.car.name)}${x.car.archived?' · Archived':''}</h3><p>${esc(x.name)} · ${esc(historySessionDate(x.startedAt,x.savedAt))}</p><p>${esc(x.track.name||'Unknown track')} · ${esc(x.sourceId)}</p><p>${x.metrics.validLaps} valid / ${x.metrics.totalLaps} selected laps · ${esc(x.driverNames.join(', ')||'Driver unknown')} · ${esc(x.metrics.lanes.length?'Lanes '+x.metrics.lanes.join(', '):'Lane unknown')}</p><p class="tiny muted">Accepted revision ${x.accepted.revision} · ${esc(x.provenance.kind)} · ${x.metrics.personalLaps} personal-eligible / ${x.metrics.trackLaps} track-eligible laps</p><p class="tiny muted">${x.configuration?'Captured configuration: '+esc(x.configuration.revision?.slice(0,12)||x.configuration.kind||'historical'):'Configuration unknown'} · ${esc(x.configuration?.capturedAt||x.configuration?.recordedAt||'Capture date unknown')}</p></section>`;
 const changes=SharedPaceModel.differences(a.configuration,b.configuration);
 return `<div class="shared-pace-pair mt">${details(a)}${details(b)}</div><section class="panel mt"><h3>Measured pace</h3><p class="tiny muted">Difference = B − A. Negative time is faster; negative standard deviation means a smaller spread. Invalid and pit laps are excluded. Sustained runs require explicit consecutive laps in one heat, stint, driver and lane; missing timing cannot establish continuity.</p>${historyTable(['Metric','A','B','Difference'],deltas)}</section><div class="note warning mt"><strong>Comparison context</strong><ul>${SharedPaceModel.warnings(a,b).map(n=>'<li>'+esc(n)+'</li>').join('')}</ul></div><section class="panel mt"><h3>Captured setup differences</h3><p class="tiny muted">The specifications recorded for these sessions. Missing values stay unknown; current car settings are never substituted. Highlighted rows differ.</p><div class="table-wrap"><table class="shared-pace-setups"><thead><tr><th>Specification</th><th>A</th><th>B</th><th>Comparison</th></tr></thead><tbody>${changes.map(r=>`<tr class="${r.status==='different'?'pace-different':''}"><th scope="row">${esc(techLabels[r.key]||r.key)}</th><td>${esc(r.left)}</td><td>${esc(r.right)}</td><td>${r.status==='unknown'?'Not established':r.status==='different'?'Different':'Same'}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function paintSharedPace(){const s=sharedPaceState;if(!sharedPaceCurrent(s))return;const root=$('#shared-pace');root.innerHTML=`<p>Compare two recorded sessions from the same car or different cars. Choose a session and its lane and driver on each side, then compare.</p><div class="actions">${btn('Refresh selections','shared-pace-refresh','small')}${btn('Manual & earlier Timing runs','shared-pace-legacy','small')}</div>${s.error?`<p class="note warning" role="alert">${esc(s.error)} Use Refresh selections to reload current history.</p>`:''}<div class="shared-pace-pair mt">${sharedPaceSide(s.left,'left')}${sharedPaceSide(s.right,'right')}</div><div class="actions mt"><button type="button" class="btn primary" data-action="shared-pace-compare" ${s.busy||s.error||s.stale||!s.left.choice||!s.right.choice?'disabled':''}>Compare recorded pace</button>${s.busy?'<span role="status">Loading comparison…</span>':''}</div>${s.result?'<div id="shared-pace-results">'+sharedPaceResults(s.result)+'</div>':''}`;if(s.busy)root.querySelectorAll('button,input,select').forEach(el=>el.disabled=true);else if(s.stale)root.querySelectorAll('input,select').forEach(el=>el.disabled=true);}
async function sharedPaceAction(action,id){
 if(!action.startsWith('shared-pace-'))return false;const s=sharedPaceState;if(!sharedPaceCurrent(s)||s.busy)return true;
 if(action==='shared-pace-legacy'){await openLegacyPace(s.left.carId);return true;}
 if(action==='shared-pace-refresh'){await openSharedPace(s.left.carId);return true;}
 if(s.stale)return true;
 if(action==='shared-pace-compare'){if(s.left.choice&&s.right.choice)await sharedPaceLoad(async()=>{const result=await sharedPaceRead(s,'pace-compare',{left:sharedPaceSelection(s.left),right:sharedPaceSelection(s.right)});if(sharedPaceCurrent(s)&&!s.stale)s.result=result;});if(s.result)$('#shared-pace-results')?.scrollIntoView({block:'start'});return true;}
 if(!['left','right'].includes(id))return true;const p=s[id];
 if(action==='shared-pace-track'){p.trackQuery=$('#shared-pace-track-'+id).value;p.sessionOffset=0;p.choice=null;p.lane='';p.driver='';await sharedPaceLoad(()=>sharedPaceSessions(s,id));}
 if(action==='shared-pace-search'){p.query=$('#shared-pace-search-'+id).value;p.carOffset=0;await sharedPaceLoad(()=>sharedPaceCars(s,id));}
 if(action==='shared-pace-cars-prev'||action==='shared-pace-cars-next'){p.carOffset=action.endsWith('prev')?Math.max(0,p.carOffset-20):p.cars?.nextOffset??p.carOffset;await sharedPaceLoad(()=>sharedPaceCars(s,id));}
 if(action==='shared-pace-sessions-prev'||action==='shared-pace-sessions-next'){p.sessionOffset=action.endsWith('prev')?Math.max(0,p.sessionOffset-20):p.sessions?.nextOffset??p.sessionOffset;await sharedPaceLoad(()=>sharedPaceSessions(s,id));}
 return true;
}
document.addEventListener('change',async e=>{
 const key=e.target.dataset.sharedPace,side=e.target.dataset.side,s=sharedPaceState;if(!key||!['left','right'].includes(side)||!sharedPaceCurrent(s)||s.busy||s.stale)return;const p=s[side];s.result=null;
 if(key==='car'){p.carId=e.target.value;p.sessions=null;p.choice=null;p.trackQuery='';p.sessionOffset=0;p.lane='';p.driver='';if(p.carId)await sharedPaceLoad(()=>sharedPaceSessions(s,side));else paintSharedPace();}
 if(key==='session'){p.choice=p.sessions?.rows.find(x=>sharedPaceKey(x)===e.target.value)||(p.choice&&sharedPaceKey(p.choice)===e.target.value?p.choice:null);p.lane='';p.driver='';paintSharedPace();}
 if(key==='lane'||key==='driver'){p[key]=e.target.value;paintSharedPace();}
});
function invalidateSharedPace(change){const s=sharedPaceState;if(!sharedPaceCurrent(s)||change?.databaseId&&change.databaseId!==s.identity.databaseId)return;s.stale=true;++s.serial;s.busy=false;s.result=null;s.error='The collection changed. Refresh selections to compare the latest accepted history.';paintSharedPace();}
document.getElementById('dialog').addEventListener('close',()=>queueMicrotask(()=>{if(!$('#dialog').open||!$('#shared-pace'))sharedPaceState=null;}));
